<script setup lang="ts">
import {provideInputContext} from './inputAssistance'
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api} from './api'
import ExecutionJournal from './ExecutionJournal.vue'
import CourseQuiz from './CourseQuiz.vue'
import CourseFeedback from './CourseFeedback.vue'
import AiRevisionSuggestions from './AiRevisionSuggestions.vue'

const route=useRoute(),router=useRouter()
const courses=ref<any[]>([]),courseId=ref(''),data=ref<any>(),tab=ref('pages'),pageId=ref(1),language=ref('source')
const busy=ref(false),error=ref(''),message=ref(''),latestRevision=ref(''),comparison=ref<any>(),compareId=ref('')
const script=ref(''),oldText=ref(''),replacement=ref(''),correction=ref(''),resolution=ref(''),remember=ref(false)
const memberAccount=ref(''),memberRole=ref('reviewer'),comment=ref(''),exportLink=ref(''),withImages=ref(true)
const templateName=ref(''),templates=ref<any[]>([]),templateId=ref(''),topics=ref(''),batch=ref<any>()
const questionCount=ref(5),teacherQuestions=ref<any[]>([]),questionLanguage=ref('en-US')
const playingLanguage=ref('')
const video=ref<HTMLVideoElement>(),question=ref(''),answerMode=ref('simple'),answer=ref<any>(),learnerPreference=ref(''),learningLanguage=ref('en-US'),timeline=ref<any>({pages:[]})
const languages:Record<string,string>={'zh-CN':'中文','en-US':'英语','ja-JP':'日语','ko-KR':'韩语','de-DE':'德语','fr-FR':'法语','ru-RU':'俄语','es-ES':'西班牙语'}
const roleNames:Record<string,string>={owner:'所有者',editor:'编辑者',reviewer:'审阅者',learner:'学习成员'}
const typeNames:Record<string,string>={narration:'讲稿',language:'语种',translation:'翻译',terminology:'术语',speech:'语速',visual_content:'图文内容',lip_sync:'口型',layout:'排版'}
const categoryNames:Record<string,string>={translation:'翻译',narration:'讲稿',speech:'语音',avatar:'数字人',subtitles:'字幕',layout:'排版',performance:'处理速度',account:'账号',other:'其他'}
const fieldNames:Record<string,string>={title:'标题',key_points:'教学要点',formulas:'公式',script_text:'讲稿'}
function languageLabel(code:string){return code==='source'?'原语言':code==='all'?'全部语种':languages[code]||code}
const kinds:Record<string,string>={definition:'概念定义',symbol:'符号',term:'术语译法',preference:'课程要求',correction:'已采纳纠错'}
const checks:Record<string,string>={passed:'已通过',failed:'未通过',needs_review:'需审阅',not_checked:'未检查',no_issues_reported:'模型未报告问题'}
const status:Record<string,string>={queued:'排队中',working:'检查中',generating:'生成修正版',ready_for_review:'修正版待复核',failed:'失败',new:'待处理',reviewing:'处理中',resolved:'已解决',open:'待处理',in_progress:'处理中',completed:'已完成',processing:'生成中'}
const editable=computed(()=>['owner','editor'].includes(data.value?.role)),reviewable=computed(()=>['owner','editor','reviewer'].includes(data.value?.role))
const availableLanguages=computed(()=>Object.keys(data.value?.translations||{}))
const sourcePage=computed(()=>data.value?.pages?.find((p:any)=>p.page_id===pageId.value))
const selectedPage=computed(()=>language.value==='source'?sourcePage.value:data.value?.translations?.[language.value]?.find((p:any)=>p.page_id===pageId.value))
const currentOutput=computed(()=>data.value?.task?.outputs?.s5?.languages?.[learningLanguage.value]||{})
const tabs=computed(()=>[{id:'pages',name:'逐页内容'},...(editable.value?[{id:'ai-suggestions',name:'AI 修改建议'}]:[]),{id:'learning',name:'学习与练习'},...(reviewable.value?[{id:'quality',name:'质量检查'},{id:'memory',name:'课程记忆'},{id:'feedback',name:'反馈与修正'},{id:'collaboration',name:'协作审阅'}]:[]),{id:'versions',name:'版本与发布'},...(editable.value?[{id:'templates',name:'模板与批量制作'}]:[])])
let serial=0,poll:ReturnType<typeof setTimeout>|undefined
async function post(path:string,payload:any){return api<any>(path,{method:'POST',body:JSON.stringify(payload),signal:AbortSignal.timeout(600000)})}
async function action(name:string,payload:any={}){return post('/v1/studio/courses/'+encodeURIComponent(courseId.value)+'/'+name,payload)}
async function perform(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function refresh(){if(!courseId.value)return;const n=++serial;const result=await api<any>('/v1/studio/courses/'+encodeURIComponent(courseId.value));if(n!==serial)return;data.value=result;if(!result.pages.some((p:any)=>p.page_id===pageId.value))pageId.value=result.pages[0]?.page_id||1;if(language.value!=='source'&&!result.translations[language.value])language.value='source';if(!result.task.outputs?.s5?.languages?.[learningLanguage.value])learningLanguage.value=Object.keys(result.task.outputs?.s5?.languages||{})[0]||Object.keys(result.translations)[0]||'en-US';learnerPreference.value=result.learning?.progress?.preference||'';if(!tabs.value.some(x=>x.id===tab.value))tab.value='pages';if(poll)clearTimeout(poll);if(result.repairs?.some((x:any)=>['queued','working','generating'].includes(x.status)))poll=setTimeout(()=>refresh().catch(()=>{}),5000)}
async function selectCourse(){data.value=undefined;latestRevision.value='';comparison.value=undefined;exportLink.value='';answer.value=undefined;pageId.value=1;await perform(refresh)}
onMounted(async()=>{await perform(async()=>{courses.value=await api<any[]>('/v1/studio/courses');templates.value=await api<any[]>('/v1/studio/templates');const requested=String(route.query.id||route.query.course||'');courseId.value=courses.value.some(x=>x.id===requested)?requested:courses.value[0]?.id||'';await refresh()})})
watch([selectedPage,language,courseId],([page,locale,course],[before,oldLocale,oldCourse])=>{const changed=locale!==oldLocale||course!==oldCourse||page?.page_id!==before?.page_id;if(changed||script.value===(before?.script_text||''))script.value=page?.script_text||'';if(changed){oldText.value='';replacement.value=''}})
watch([currentOutput,learningLanguage],async()=>{try{timeline.value=currentOutput.value.timeline?await api<any>(currentOutput.value.timeline):{pages:[]}}catch{timeline.value={pages:[]}}})
onUnmounted(()=>{serial++;if(poll)clearTimeout(poll)})
async function revise(changes:any[]){await perform(async()=>{const result=await action('revise',{changes,execute:true});latestRevision.value=result.task.id;message.value='修订版已创建，原课程保留。可在新任务中查看生成进度。';await refresh()})}
function editScript(){if(data.value.task.status==='waiting_review'){void perform(async()=>{await action('draft',{page:pageId.value,language:language.value,text:script.value,revision:data.value.task.draftRevision||0});await refresh();message.value='讲稿草稿已保存。'})}else return revise([{page:pageId.value,language:language.value,kind:'script',text:script.value}])}
function approve(){void perform(async()=>{await action('approve');await refresh();message.value='已提交后续生成。'})}
function editText(kind='slide_text'){return revise([{page:pageId.value,language:language.value,kind,oldText:oldText.value,text:replacement.value}])}
function regenerate(kind:string){return revise([{page:pageId.value,language:language.value,kind}])}
function addMemory(){data.value.memory.entries.push({kind:'definition',name:'',value:'',pages:[pageId.value],language:'all',status:'candidate'})}
function saveMemory(){void perform(async()=>{await action('memory',data.value.memory);await refresh();message.value='课程记忆已保存。已采纳的内容可用于后续课程。'})}
function extractMemory(){void perform(async()=>{await action('extract-memory');await refresh();message.value='已提取候选，请检查后选择采纳。'})}
async function reviewPages(all=false){await perform(async()=>{const pages=all?data.value.pages:[sourcePage.value];for(const p of pages){message.value='正在审阅第 '+p.page_id+' 页';await action('review',{page:p.page_id,withImages:withImages.value})}await refresh();message.value='内容审阅已结束，请查看逐页结果。'})}
function repair(row:any){void perform(async()=>{const result=await action('repair',{feedbackId:row.id,page:row.page||pageId.value,language:row.language||(language.value==='source'?availableLanguages.value[0]:language.value),correction:correction.value,oldText:oldText.value});message.value='已提交反馈处理，状态：'+(status[result.status]||result.status);await refresh()})}
function resolveFeedback(row:any){void perform(async()=>{await action('resolve-feedback',{feedbackId:row.id,note:resolution.value,remember:remember.value});await refresh();message.value='处理说明已保存。'})}
function saveComment(){void perform(async()=>{await action('comment',{page:pageId.value,text:comment.value});comment.value='';await refresh()})}
function commentStatus(row:any,state:string){void perform(async()=>{await action('comment',{id:row.id,status:state,resolution:resolution.value});await refresh()})}
function member(role=memberRole.value,userId?:string){void perform(async()=>{await action('members',{account:memberAccount.value,role,userId});memberAccount.value='';await refresh()})}
function compare(){void perform(async()=>{comparison.value=await action('compare',{versionId:compareId.value})})}
function publish(id:string,state:string){void perform(async()=>{await post('/v1/studio/courses/'+encodeURIComponent(id)+'/publish',{status:state});await refresh();message.value=state==='published'?'此版本已向受邀学习成员发布。':'此版本已设为私有。'})}
function exportCourse(){void perform(async()=>{const result=await action('export');exportLink.value=result.download;message.value='SCORM 1.2 课程包已生成。'})}
function saveTemplate(){void perform(async()=>{await post('/v1/studio/templates',{courseId:courseId.value,name:templateName.value});templates.value=await api<any[]>('/v1/studio/templates');message.value='课程模板已保存。'})}
function launchBatch(){void perform(async()=>{batch.value=await post('/v1/studio/templates/'+encodeURIComponent(templateId.value)+'/launch',{topics:topics.value.split('\n').map(x=>x.trim()).filter(Boolean),targetLanguages:availableLanguages.value.length?availableLanguages.value:['zh-CN'],execute:true});message.value='批量任务已创建，请查看各任务状态。'})}
async function saveProgress(){if(!data.value)return;try{await action('learning',{page:pageId.value,seconds:video.value?.currentTime||0,language:playingLanguage.value||learningLanguage.value,preference:learnerPreference.value})}catch(e){error.value=(e as Error).message}}
async function resumePlayback(){const saved=data.value.learning.progress;if(saved.language&&availableLanguages.value.includes(saved.language))learningLanguage.value=saved.language;await nextTick();if(video.value){const media=video.value;const seek=()=>{media.currentTime=saved.seconds||0};if(media.readyState>=1)seek();else media.addEventListener('loadedmetadata',seek,{once:true})}}
function currentPosition(){const t=video.value?.currentTime||0;const page=timeline.value.pages?.find((x:any)=>t>=Number(x.start_time??x.start)&&t<Number(x.end_time??x.end));if(page)pageId.value=Number(page.page_id)}
function ask(){void perform(async()=>{answer.value=await action('ask',{page:pageId.value,language:learningLanguage.value,question:question.value,mode:answerMode.value});await refresh()})}
function openTask(id:string){void router.push('/task?id='+encodeURIComponent(id))}
function loadQuestions(){void perform(async()=>{teacherQuestions.value=await api<any[]>('/v1/courses/'+courseId.value+'/teacher/questions')})}
function generateQuestions(){void perform(async()=>{await post('/v1/courses/'+courseId.value+'/questions/batch',{count:questionCount.value,locale:questionLanguage.value});teacherQuestions.value=await api<any[]>('/v1/courses/'+courseId.value+'/teacher/questions');message.value='题目草稿已生成，审核后向学生展示。'})}
function approveQuestion(row:any,approved:boolean){void perform(async()=>{await post('/v1/questions/'+row.question_id+'/review',{approved});teacherQuestions.value=await api<any[]>('/v1/courses/'+courseId.value+'/teacher/questions')})}
provideInputContext(()=>({courseId:courseId.value||undefined,page:pageId.value,language:language.value==='source'?data.value?.task?.sourceLanguage:language.value,context:{courseName:data.value?.task?.name,section:tab.value,page:selectedPage.value}}))
</script>
<template>
 <div class="course-workspace">
  <div class="heading"><div><a href="#/planner">课程方案与系列制作</a><h1>课程工作区</h1><p>逐页审阅、修订、课程记忆、协作与学习。</p></div></div>
  <div class="toolbar panel"><label>课程<select v-model="courseId" @change="selectCourse"><option v-for="item in courses" :key="item.id" :value="item.id">{{item.name}} · {{item.role==='owner'?'我的课程':roleNames[item.role]}}</option></select></label><button :disabled="busy||!courseId" @click="perform(refresh)">刷新</button></div>
  <p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p>
  <p v-if="latestRevision" class="notice">修订任务：<button @click="openTask(latestRevision)">打开修订版</button></p>
  <div v-if="data" :aria-busy="busy"><p v-if="data.task.status==='waiting_review'" class="notice">讲稿与译文正在等待审阅。<button v-if="editable" :disabled="busy" @click="approve">审阅完成，继续生成</button></p>
   <nav class="tabs"><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id">{{item.name}}</button></nav>
   <div v-if="['pages','quality','feedback','collaboration','learning','ai-suggestions'].includes(tab)" class="selectors"><label>页码<select v-model.number="pageId"><option v-for="p in data.pages" :key="p.page_id" :value="p.page_id">第 {{p.page_id}} 页 · {{p.title}}</option></select></label><label v-if="tab==='pages'">内容语种<select v-model="language"><option value="source">原始内容</option><option v-for="code in availableLanguages" :key="code" :value="code">{{languages[code]||code}}</option></select></label></div>
   <section v-if="tab==='pages'" class="panel">
    <div class="page-grid"><div><h3>原始页面与讲稿</h3><img v-if="sourcePage?.image" :src="sourcePage.image" alt="原始课件页面"><h4>{{sourcePage?.title}}</h4><ul><li v-for="point in sourcePage?.key_points" :key="point">{{point}}</li></ul><p class="pre">{{sourcePage?.script_text}}</p></div><div><h3>{{language==='source'?'原语言讲稿':'目标语种讲稿'}}</h3><p>修改后创建独立修订版，原课程保留。</p><AssistedTextarea v-model="script" rows="16" :readonly="!editable" assist-label="页面讲稿" assist-purpose="lecture"/><button v-if="editable" :disabled="busy||!script.trim()||!['completed','waiting_review'].includes(data.task.status)" @click="editScript">保存为修订版并生成</button><div v-if="editable" class="edit-block"><label>待替换原文<input v-model="oldText"></label><label>正确文字<AssistedTextarea v-model="replacement" rows="3" assist-label="课件或字幕替换文字" assist-purpose="lecture"/></label><button :disabled="busy||!oldText||!replacement" @click="editText()">修订课件文字</button><button v-if="language!=='source'" :disabled="busy||!oldText||!replacement" @click="editText('subtitle')">仅修订字幕</button></div></div></div>
    <div v-if="editable" class="actions"><button :disabled="busy" @click="regenerate('speech')">重新生成本页语音及后续结果</button><button :disabled="busy" @click="regenerate('avatar')">重新生成本页数字人</button><button :disabled="busy" @click="regenerate('layout')">使用右侧讲者区域重新合成</button></div>
   </section>
   <section v-else-if="tab==='ai-suggestions'" class="panel"><AiRevisionSuggestions :course-id="courseId" :page="pageId" :language="language" :languages="languages" :available-languages="availableLanguages" :records="data.revisionSuggestions||[]" :completed="data.task.status==='completed'" @refresh="refresh" @created="latestRevision=$event"/></section>
   <section v-else-if="tab==='quality'" class="panel"><h3>检查结果</h3><p>文字、翻译和语速使用实际检查记录。未执行的项目单独列出。</p><div class="actions"><span v-for="(count,state) in data.quality.counts" :key="state">{{checks[String(state)]||state}}：{{count}}</span></div><label><input v-model="withImages" type="checkbox">内容审阅同时读取课件画面</label><div class="actions"><button :disabled="busy" @click="reviewPages()">审阅当前页</button><button :disabled="busy" @click="reviewPages(true)">逐页审阅整门课</button></div><div class="table-wrap"><table><thead><tr><th>页码</th><th>语种</th><th>项目</th><th>状态</th><th>说明</th></tr></thead><tbody><tr v-for="(row,i) in data.quality.checks" :key="i"><td>{{row.page||'整体'}}</td><td>{{languageLabel(row.language)}}</td><td>{{typeNames[row.type]||row.type}}</td><td>{{checks[row.status]}}</td><td>{{row.message}}</td></tr></tbody></table></div><article v-for="row in data.modelReviews" :key="row.id"><h4>第 {{row.page}} 页 · {{checks[row.status]||row.status}}</h4><p>{{row.summary||row.message}}</p><p>读取图片：{{row.imageReviewed?'是':'否'}} · 尝试 {{row.attempts}} 次</p><ul><li v-for="(issue,i) in row.issues" :key="i">{{issue.message}}<p>{{issue.suggestion}}</p><blockquote v-if="issue.quote">{{issue.quote}}</blockquote></li></ul></article><ExecutionJournal :task-id="courseId"/></section>
   <section v-else-if="tab==='memory'" class="panel"><h3>课程记忆 · 版本 {{data.memory.revision}}</h3><p>保存概念定义、符号、术语和已采纳的纠错。新课程选择此课程作为记忆来源后使用已采纳内容。</p><div v-if="editable" class="actions"><button :disabled="busy" @click="addMemory">添加记忆</button><button :disabled="busy" @click="extractMemory">从课程提取候选</button><button :disabled="busy" @click="saveMemory">保存记忆</button></div><article v-for="(entry,i) in data.memory.entries" :key="entry.id||i"><div class="inline"><select v-model="entry.kind" :disabled="!editable"><option v-for="(name,key) in kinds" :key="key" :value="key">{{name}}</option></select><select v-model="entry.language" :disabled="!editable"><option value="all">全课程</option><option v-for="(name,code) in languages" :key="code" :value="code">{{name}}</option></select><select v-model="entry.status" :disabled="!editable"><option value="candidate">待审阅候选</option><option value="accepted">已采纳</option></select><button v-if="editable" @click="data.memory.entries.splice(i,1)">移除</button></div><label>概念、符号或原文<AssistedInput v-model="entry.name" maxlength="160" :readonly="!editable" assist-label="课程记忆名称" assist-purpose="memory" :assist-context="{name:entry.name,value:entry.value}"/></label><label>定义、要求或指定译法<AssistedTextarea v-model="entry.value" rows="3" maxlength="1200" :readonly="!editable" assist-label="课程定义、要求或译法" assist-purpose="memory" :assist-context="{name:entry.name,value:entry.value}"/></label><label>来源页面<select v-model="entry.pages" multiple :disabled="!editable"><option v-for="p in data.pages" :key="p.page_id" :value="p.page_id">第 {{p.page_id}} 页</option></select></label></article></section>
   <section v-else-if="tab==='feedback'" class="panel"><h3>反馈与修正</h3><p>反馈未标记页码时，使用上方当前页；未标记语种时，使用课程的第一个目标语种。</p><label>期望的正确内容或修正要求<AssistedTextarea v-model="correction" rows="3" assist-label="反馈修正要求" assist-purpose="requirements"/></label><label>字幕待替换原文（处理字幕反馈时填写）<input v-model="oldText"></label><article v-for="row in data.feedback" :key="row.id"><h4>{{row.rating?row.rating+' / 5 分':'文字反馈'}} · {{row.language?languages[row.language]:''}} · {{row.page?'第 '+row.page+' 页':'未标记页码'}}</h4><p>{{row.categories.map((x:string)=>categoryNames[x]||x).join('、')}} · {{status[row.status]||row.status}}</p><p class="pre">{{row.comment}}</p><p v-if="row.playbackSeconds!=null">播放位置：{{row.playbackSeconds}} 秒</p><button v-if="editable&&row.categories.some((x:string)=>['translation','narration','speech','subtitles','avatar','layout'].includes(x))" :disabled="busy" @click="repair(row)">检查并生成修订版</button><button v-if="editable&&resolution.trim()" :disabled="busy" @click="resolveFeedback(row)">保存处理说明并标记解决</button></article><p v-if="!data.feedback.length">暂无课程反馈。</p><h4>修正任务</h4><article v-for="row in data.repairs" :key="row.id"><p>第 {{row.page}} 页 · {{languages[row.language]}} · {{status[row.status]||row.status}}</p><p>{{row.message}}</p><button v-if="row.releaseTaskId" @click="openTask(row.releaseTaskId)">查看修订版</button></article><label v-if="editable">处理说明<AssistedTextarea v-model="resolution" rows="3" assist-label="处理与审阅说明" assist-purpose="review"/></label><label v-if="editable"><input v-model="remember" type="checkbox">将处理说明保存为已采纳的课程纠错记忆</label></section>
   <section v-else-if="tab==='collaboration'" class="panel"><h3>逐页协作审阅</h3><label>当前页评论<AssistedTextarea v-model="comment" rows="3" maxlength="3000" assist-label="课程审阅意见" assist-purpose="review"/></label><button :disabled="busy||!comment.trim()" @click="saveComment">提交评论</button><article v-for="row in data.comments" :key="row.id"><h4>第 {{row.page||'整体'}} 页 · {{status[row.status]||row.status}}</h4><p class="pre">{{row.text}}</p><p>{{row.resolution}}</p><div v-if="editable" class="actions"><button :disabled="busy" @click="commentStatus(row,'in_progress')">处理中</button><button :disabled="busy" @click="commentStatus(row,'resolved')">已处理</button><button :disabled="busy" @click="commentStatus(row,'open')">重新打开</button></div></article><div v-if="data.role==='owner'"><h3>协作成员</h3><p>编辑者可以修改课程，审阅者可以查看与评论，学习成员仅能访问已发布课程。</p><label>已注册账号<input v-model="memberAccount" autocomplete="off"></label><select v-model="memberRole"><option value="editor">编辑者</option><option value="reviewer">审阅者</option><option value="learner">学习成员</option></select><button :disabled="busy||!memberAccount" @click="member()">添加或更新成员</button><p v-for="(row,id) in data.members" :key="id">{{row.displayName}} · {{roleNames[row.role]||row.role}} <button :disabled="busy" @click="member('remove',String(id))">移除</button></p></div></section>
   <section v-else-if="tab==='versions'" class="panel"><h3>课程版本与发布</h3><p>发布仅向已添加的学习成员开放课程。</p><article v-for="row in data.versions" :key="row.id"><h4>{{row.name}}</h4><p>{{status[row.status]||row.status}} · {{row.createdAt}} · {{row.publication?.status==='published'?'已发布':'私有'}}</p><button @click="openTask(row.id)">查看版本</button><template v-if="data.role==='owner'"><button :disabled="busy||row.status!=='completed'" @click="publish(row.id,'published')">发布此版本</button><button :disabled="busy" @click="publish(row.id,'private')">设为私有</button></template></article><div v-if="editable"><h4>版本比较</h4><select v-model="compareId"><option value="">选择比较版本</option><option v-for="row in data.versions.filter((x:any)=>x.id!==courseId)" :key="row.id" :value="row.id">{{row.name}} · {{row.createdAt}}</option></select><button :disabled="busy||!compareId" @click="compare">比较逐页内容</button><article v-for="(row,i) in comparison?.changes||[]" :key="i"><h4>{{languageLabel(row.language)}} · 第 {{row.page}} 页 · {{fieldNames[row.field]||row.field}}</h4><p class="pre">原内容：{{row.before}}</p><p class="pre">当前内容：{{row.after}}</p></article><p v-if="comparison&&!comparison.changes.length">页面文字与讲稿一致，媒体或字幕修改请比较对应视频。</p></div><div v-if="data.role==='owner'"><h4>学习平台课程包</h4><button :disabled="busy||data.task.status!=='completed'" @click="exportCourse">生成 SCORM 1.2 课程包</button><a v-if="exportLink" :href="exportLink">下载课程包</a></div></section>
   <section v-else-if="tab==='templates'" class="panel"><h3>课程模板与系列制作</h3><p>模板保存讲者素材、音色和常用课程参数，并沿用此课程已采纳的记忆。</p><label>模板名称<AssistedInput v-model="templateName" maxlength="120" assist-label="课程模板名称" assist-purpose="topic"/></label><button :disabled="busy||!templateName" @click="saveTemplate">保存当前课程为模板</button><h4>批量制作课程</h4><select v-model="templateId"><option value="">选择我的课程模板</option><option v-for="item in templates" :key="item.id" :value="item.id">{{item.name}}</option></select><label>课程主题，每行一个，最多 12 个<AssistedTextarea v-model="topics" rows="6" assist-label="批量课程主题（每行一个）" assist-purpose="batch_topics"/></label><button :disabled="busy||!templateId||!topics.trim()" @click="launchBatch">创建批量任务并开始生成</button><div v-if="batch"><p>已创建 {{batch.taskIds.length}} 个任务</p><button v-for="id in batch.taskIds" :key="id" @click="openTask(id)">查看任务 {{id}}</button><p v-for="row in batch.errors" :key="row.taskId">{{row.message}}</p></div></section>
   <section v-else-if="tab==='learning'" class="panel"><h3>课程学习与练习</h3><label>学习语种<select v-model="learningLanguage"><option v-for="code in availableLanguages" :key="code" :value="code">{{languages[code]}}</option></select></label><video v-if="currentOutput.video||currentOutput.finalVideo" ref="video" :src="currentOutput.video||currentOutput.finalVideo" controls preload="metadata" @loadedmetadata="playingLanguage=learningLanguage" @timeupdate="currentPosition" @pause="saveProgress"/><p v-if="data.learning.progress?.page">上次学习：第 {{data.learning.progress.page}} 页，{{data.learning.progress.seconds}} 秒 <button @click="resumePlayback">继续播放</button></p><label>我的解释偏好<AssistedInput v-model="learnerPreference" maxlength="500" placeholder="例如：先解释术语，再给一个基础例子" assist-label="个人学习偏好" assist-purpose="question"/></label><button :disabled="busy" @click="saveProgress">保存学习位置与偏好</button><p>已作答 {{data.learning.answeredQuestions}} 题，最近作答正确 {{data.learning.latestCorrect}} 题。</p><p v-if="data.learning.reviewPages.length">建议复习：第 {{data.learning.reviewPages.join('、')}} 页。</p><CourseQuiz :course-id="courseId" :language="learningLanguage" :media="video" :timeline="timeline"/><h4>围绕课程提问</h4><select v-model="answerMode"><option value="simple">基础解释</option><option value="detailed">详细说明</option><option value="example">结合例子</option><option value="summary">复习提纲</option></select><AssistedTextarea v-model="question" rows="3" maxlength="4000" placeholder="填写当前知识点的问题" assist-label="课程学习提问" assist-purpose="question"/><button :disabled="busy||!question.trim()" @click="ask">根据课程资料回答</button><article v-if="answer"><p class="pre">{{answer.answer}}</p><p v-if="answer.insufficient">课程资料不足以完整回答，回答中已说明限制。</p><blockquote v-for="(ref,i) in answer.sources" :key="i">第 {{ref.page}} 页：{{ref.quote}}</blockquote></article><details><summary>我的历史问答</summary><article v-for="row in data.learning.answers" :key="row.id"><h4>{{row.question}}</h4><p class="pre">{{row.answer}}</p></article></details><CourseFeedback :task="data.task" :language="learningLanguage" :media="video" :page-id="pageId"/><div v-if="editable"><h3>题目生成与审核</h3><div class="inline"><select v-model="questionLanguage"><option v-for="(name,code) in languages" :key="code" :value="code">{{name}}</option></select><input v-model.number="questionCount" type="number" min="1" max="20"><button :disabled="busy" @click="generateQuestions">根据课程生成题目</button><button :disabled="busy" @click="loadQuestions">查看题目草稿</button></div><article v-for="row in teacherQuestions" :key="row.question_id"><h4>{{row.prompt}} · {{row.status}}</h4><p v-for="option in row.options" :key="option.id">{{option.text}} {{row.correct_option_id===option.id?'（正确选项）':''}}</p><button :disabled="busy" @click="approveQuestion(row,true)">审核通过</button><button :disabled="busy" @click="approveQuestion(row,false)">不通过</button></article></div></section>
  </div><p v-else-if="!busy&&!courses.length" class="notice">创建课程后，在这里管理逐页内容和后续修订。受邀课程也会显示在此处。</p>
 </div>
</template>
