urse-workspace h3{font-size:17px}.course-workspace h4{font-size:14px}.actions{margin:12px 0;font-size:12px}@media(max-width:760px){.page-grid{grid-template-columns:1fr}.panel{padding:14px}.selectors label{max-width:100%}.toolbar{align-items:stretch}.toolbar label{width:100%}.toolbar select{width:100%}}
